import { unzip, unzipSync } from './vendor/fflate/browser.js';

const URDF_PACK_MANIFEST = 'manifest.json';
const URDF_PACK_SCHEMAS = new Set([1, 2]);
const UTF8 = new TextDecoder('utf-8');

function safeArchivePath(value) {
  const text = String(value || '')
    .replace(/\\/g, '/')
    .replace(/^\/+/, '')
    .split(/[?#]/, 1)[0];
  const parts = text.split('/').filter(Boolean);
  if (!parts.length || parts.some((part) => part === '.' || part === '..')) return '';
  return parts.join('/');
}

function normalizeReference(value) {
  let text = String(value || '').trim();
  if (text.startsWith('package://')) {
    const rest = text.slice('package://'.length);
    const slash = rest.indexOf('/');
    text = slash >= 0 ? rest.slice(slash + 1) : '';
  } else if (text.startsWith('file://')) {
    text = text.slice('file://'.length);
  }
  try { text = decodeURIComponent(text); } catch {}
  return safeArchivePath(text);
}

function encodeVirtualPath(path) {
  return safeArchivePath(path)
    .split('/')
    .map((part) => encodeURIComponent(part))
    .join('/');
}

function unzipArchive(bytes) {
  if (typeof Worker !== 'function') {
    return Promise.resolve(unzipSync(bytes));
  }
  return new Promise((resolve, reject) => {
    try {
      unzip(bytes, (error, files) => {
        if (!error) {
          resolve(files || {});
          return;
        }
        // Some browsers or embedded WebViews disallow Blob workers. Keep the
        // one-request transport available by falling back to synchronous
        // decompression before abandoning the archive entirely.
        try { resolve(unzipSync(bytes)); }
        catch (fallbackError) { reject(fallbackError || error); }
      });
    } catch (error) {
      try { resolve(unzipSync(bytes)); }
      catch (fallbackError) { reject(fallbackError || error); }
    }
  });
}

async function fetchArchiveBytes(url, onProgress) {
  const response = await fetch(url, {
    credentials: 'same-origin',
    cache: 'force-cache',
  });
  if (!response.ok) {
    throw new Error(`failed to load packed robot assets (${response.status})`);
  }

  const declared = Number(response.headers.get('content-length')) || 0;
  if (!response.body?.getReader) {
    const bytes = new Uint8Array(await response.arrayBuffer());
    onProgress?.({ stage: 'Downloaded packed robot', progress: 0.72, loaded: bytes.byteLength, total: declared || bytes.byteLength });
    return bytes;
  }

  const reader = response.body.getReader();
  const chunks = [];
  let loaded = 0;
  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    if (!value?.byteLength) continue;
    chunks.push(value);
    loaded += value.byteLength;
    const fraction = declared > 0 ? loaded / declared : 0;
    onProgress?.({
      stage: 'Downloading packed robot',
      progress: Math.min(0.72, Math.max(0, fraction) * 0.72),
      loaded,
      total: declared,
    });
  }
  const bytes = new Uint8Array(loaded);
  let offset = 0;
  for (const chunk of chunks) {
    bytes.set(chunk, offset);
    offset += chunk.byteLength;
  }
  return bytes;
}

function validateManifest(manifest, bundle, files) {
  if (!manifest || !URDF_PACK_SCHEMAS.has(Number(manifest.schema)) || manifest.format !== 'puddleduck-urdf-pack') {
    throw new Error('unsupported packed robot manifest');
  }
  const requestedUrdf = safeArchivePath(bundle?.archive_urdf || bundle?.urdf_name || manifest.urdf);
  if (!requestedUrdf || !files[requestedUrdf]) {
    throw new Error(`packed robot does not contain its selected URDF (${requestedUrdf || 'missing'})`);
  }
  const declaredUrdfs = Array.isArray(manifest.urdfs)
    ? new Set(manifest.urdfs.map(safeArchivePath).filter(Boolean))
    : new Set([safeArchivePath(manifest.urdf)].filter(Boolean));
  if (declaredUrdfs.size && !declaredUrdfs.has(requestedUrdf)) {
    throw new Error(`packed robot did not declare its selected URDF (${requestedUrdf})`);
  }
  if (bundle?.asset_version && manifest.asset_version !== bundle.asset_version) {
    throw new Error(`packed robot version mismatch (${manifest.asset_version || 'missing'} != ${bundle.asset_version})`);
  }
  const declared = Array.isArray(manifest.files) ? manifest.files : [];
  for (const entry of declared) {
    const path = safeArchivePath(typeof entry === 'string' ? entry : entry?.path);
    if (!path || !files[path]) throw new Error(`packed robot is missing ${path || 'an invalid file'}`);
  }
  return requestedUrdf;
}

function rewriteUrdfFilenames(urdfText, resolveEntry, virtualUrl) {
  return String(urdfText || '').replace(
    /(filename\s*=\s*)(["'])([^"']+)(\2)/gi,
    (match, prefix, quote, reference) => {
      const path = resolveEntry(reference);
      if (!path) return match;
      return `${prefix}${quote}${virtualUrl(path)}${quote}`;
    },
  );
}

/**
 * Fetch and unpack a PuddleDuck URDF ZIP archive.
 *
 * The returned object exposes one synthetic URL namespace. Three.js receives
 * stable, path-preserving virtual URLs and its LoadingManager translates them
 * to object URLs lazily. This keeps nested DAE/OBJ/GLTF texture references in
 * the same archive without issuing network requests.
 */
export async function loadUrdfZipPack(bundle, options = {}) {
  const archiveUrl = String(bundle?.archive_url || '').trim();
  if (!archiveUrl) return null;
  const onProgress = typeof options.onProgress === 'function' ? options.onProgress : null;
  const bytes = await fetchArchiveBytes(archiveUrl, onProgress);
  onProgress?.({ stage: 'Unpacking packed robot', progress: 0.76, loaded: bytes.byteLength, total: bytes.byteLength });
  const files = await unzipArchive(bytes);
  const manifestBytes = files[URDF_PACK_MANIFEST];
  if (!manifestBytes) throw new Error(`packed robot does not contain ${URDF_PACK_MANIFEST}`);

  let manifest;
  try {
    manifest = JSON.parse(UTF8.decode(manifestBytes));
  } catch (error) {
    throw new Error(`invalid packed robot manifest: ${error?.message || error}`);
  }
  const urdfPath = validateManifest(manifest, bundle, files);
  const entries = new Map();
  const mime = new Map();
  for (const entry of manifest.files || []) {
    const path = safeArchivePath(typeof entry === 'string' ? entry : entry?.path);
    if (!path || !files[path]) continue;
    entries.set(path, files[path]);
    mime.set(path, String(typeof entry === 'string' ? '' : entry?.mime || 'application/octet-stream'));
  }

  const aliases = new Map();
  for (const [raw, target] of Object.entries(manifest.aliases || {})) {
    const path = safeArchivePath(target);
    if (!path || !entries.has(path)) continue;
    aliases.set(String(raw), path);
    const normalized = normalizeReference(raw);
    if (normalized) aliases.set(normalized, path);
  }
  for (const path of entries.keys()) aliases.set(path, path);

  const packId = encodeURIComponent(String(manifest.asset_version || bundle.asset_version || Date.now()));
  const virtualRoot = `https://puddleduck-urdf.invalid/${packId}/`;
  const objectUrls = new Map();

  const resolveEntry = (value) => {
    const raw = String(value || '');

    // When the URDF itself is loaded from a blob URL, URL resolution inside
    // URDFLoader/Three.js may turn an absolute virtual asset URL into a string
    // such as:
    //
    //   blob:http://robot/https://puddleduck-urdf.invalid/<pack>/assets/x.stl
    //
    // The virtual URL is still present verbatim, so recover it before normal
    // alias/path handling.  Without this, FileLoader tries to fetch the
    // malformed composite blob URL and reports ERR_FILE_NOT_FOUND.
    const embeddedVirtual = raw.indexOf(virtualRoot);
    if (embeddedVirtual >= 0) {
      let relative = raw.slice(embeddedVirtual + virtualRoot.length);
      relative = relative.split(/[?#]/, 1)[0];
      try { relative = decodeURIComponent(relative); } catch {}
      const path = safeArchivePath(relative);
      return entries.has(path) ? path : '';
    }
    if (aliases.has(raw)) return aliases.get(raw);
    const normalized = normalizeReference(raw);
    if (aliases.has(normalized)) return aliases.get(normalized);
    if (entries.has(normalized)) return normalized;
    try {
      const url = new URL(raw);
      const virtual = `${url.protocol}//${url.host}${url.pathname}`;
      if (virtual.startsWith(virtualRoot)) {
        let relative = virtual.slice(virtualRoot.length);
        try { relative = decodeURIComponent(relative); } catch {}
        const path = safeArchivePath(relative);
        return entries.has(path) ? path : '';
      }
    } catch {}
    return '';
  };

  const virtualUrl = (path) => `${virtualRoot}${encodeVirtualPath(path)}`;
  const objectUrlFor = (value) => {
    const path = resolveEntry(value);
    if (!path) return '';
    if (objectUrls.has(path)) return objectUrls.get(path);
    const bytesForFile = entries.get(path);
    const url = URL.createObjectURL(new Blob([bytesForFile], { type: mime.get(path) || 'application/octet-stream' }));
    objectUrls.set(path, url);
    return url;
  };

  const rewrittenUrdf = rewriteUrdfFilenames(
    UTF8.decode(entries.get(urdfPath)),
    resolveEntry,
    virtualUrl,
  );
  const urdfUrl = URL.createObjectURL(new Blob([rewrittenUrdf], { type: 'application/xml' }));
  objectUrls.set('__urdf__', urdfUrl);
  onProgress?.({
    stage: 'Packed robot ready',
    progress: 1,
    loaded: Number(manifest.total_bytes) || 0,
    total: Number(manifest.total_bytes) || 0,
  });

  return {
    key: archiveUrl,
    archiveUrl,
    manifest,
    urdfUrl,
    virtualRoot,
    virtualUrl,
    fileCount: entries.size,
    totalBytes: Number(manifest.total_bytes) || 0,
    resolveEntry,
    objectUrlFor,
    installManager(manager) {
      if (!manager?.setURLModifier) return;
      manager.setURLModifier((url) => objectUrlFor(url) || url);
    },
    dispose() {
      for (const url of objectUrls.values()) {
        try { URL.revokeObjectURL(url); } catch {}
      }
      objectUrls.clear();
      entries.clear();
      aliases.clear();
    },
  };
}

export { normalizeReference, rewriteUrdfFilenames, safeArchivePath };
